 let writes=0,active=true;const rows=async type=>(await db.query('select to_jsonb(r) r from public.cc_records r where item_type=$1 order by id',[type])).rows.map(v=>v.r),get=async id=>(await db.query('select to_jsonb(r) r from public.cc_records r where id=$1',[id])).rows.map(v=>v.r);
 const api={signIn:async()=>({accessToken:'FICTIONAL_ACCESS',refreshToken:'FICTIONAL_REFRESH',expiresAt:now+3600000}),getUser:async()=>({id:owner,email:'demo@example.test'}),isSessionActive:async()=>active,signOutLocal:async()=>{},refreshSession:async()=>{throw Error('Unexpected refresh');},listPrivateBriefRecords:async()=>[],listPrivateProjects:async()=>rows('project'),getPrivateProject:async(_t,id)=>get(id),addPrivateProject:async()=>{throw Error('No project copies');},updatePrivateProject:async()=>{throw Error('No project edits');},listPrivateSchoolSummaries:async()=>(await rows('school_fixture')).map(r=>{for(const k of ['notes','assessments','studySessions'])delete r.payload[k];return r;}),getPrivateSchoolRecord:async(_t,id)=>get(id),listProjectTaskChoices:async()=>rows('task'),getProjectTaskChoice:async(_t,id)=>get(id),getProjectLinkTarget:async(_t,id)=>get(id),listProjectTaskMemberships:async(_t,key)=>(await rows('project_task_link')).filter(r=>r.payload.projectId===key),getTaskProjectMembership:async()=>[],setTaskProjectLink:async()=>{throw Error('No ordinary writes');},listCommonTaskMemberships:async()=>rows('common_task_link'),commonTaskLinksReady:async()=>(await db.query('select public.cc_private_common_task_links_ready() ready')).rows[0].ready,getCommonTaskSource:async(_t,ref)=>get(ref.recordId),getCommonTaskMembership:async(_t,task,project)=>(await db.query("select to_jsonb(r) r from public.cc_records r where item_type='common_task_link' and cc_private.common_task_membership_key(payload->'task',payload->'project')=cc_private.common_task_membership_key($1::jsonb,$2::jsonb)",[JSON.stringify(task),JSON.stringify(project)])).rows.map(v=>v.r),setCommonTaskLink:async(_t,v)=>{writes++;return(await db.query('select public.cc_set_common_task_link($1::jsonb,$2,$3::jsonb,$4,$5,$6) result',[JSON.stringify(v.task),v.taskVersion,JSON.stringify(v.project),v.projectVersion,v.linkVersion,v.linked])).rows[0].result;}};
 if(taskEditing||taskReading){api.getPrivateTask=async(_t,key)=>get(key);api.getPrivateTaskDetails=async(_t,key)=>get(key);api.updatePrivateTask=async(_t,prior,who,payload,section)=>(await db.query("update public.cc_records set payload=$1,section=$2 where id=$3 and owner_id=$4 and version=$5 returning to_jsonb(cc_records) r",[JSON.stringify(payload),section,prior.id,who,prior.version])).rows.map(v=>v.r);}
