 if(hierarchy){api.projectHierarchySnapshot=async()=>{assert.equal((await db.query('select public.cc_project_hierarchy_single_master_ready() ready')).rows[0].ready,true);return(await db.query('select public.cc_project_hierarchy_snapshot() snapshot')).rows[0].snapshot;};api.setProjectHierarchyLink=async()=>{throw Error('Unexpected hierarchy write');};}
 const router=createPrivateSessionHttp({origin,api,now:()=>now,allowBriefRead:true,allowSchoolRead:true,allowSchoolEdit:editing,allowTaskRead:taskReading,allowTaskEdit:taskEditing,allowTaskDescriptionEdit:taskEditing,allowProjects:true,allowProjectTaskLinks:true,allowCommonTaskLinks:enabled,allowProjectHierarchy:hierarchy});t.after(()=>router.dispose());let cookie='',csrf='';
 async function call(path,body,extra={},method=body===undefined?'GET':'POST'){const req={url:'/auth/workspace/'+path,method,headers:{host:'127.0.0.1:5312',origin,cookie,'content-type':'application/json','x-cc-request':'workspace-session','x-cc-csrf':csrf,...extra},async *[Symbol.asyncIterator](){yield JSON.stringify(body);}},res={writeHead(status,headers){this.status=status;this.headers=headers;return this;},end(body){this.body=body;}};assert.equal(await router.handle(req,res),true);const data=JSON.parse(res.body);if(res.headers['Set-Cookie'])cookie=res.headers['Set-Cookie'].split(';')[0];if(data.csrf)csrf=data.csrf;return{status:res.status,data};}
