test('HTTP selected-source review approval invokes actual SQL link/unlink/relink without source copies',async t=>{const s=await setup(t),before=(await s.get(s.f.course.id))[0];for(const linked of [true,false,true]){const r=await s.review();assert.equal(r.status,200);assert.equal(r.data.linked,linked);assert.equal(JSON.stringify(r.data).includes('Exact <literal> notes'),false);assert.deepEqual(await s.call('common-tasks/save',{reviewId:r.data.reviewId,approved:true}),{status:200,data:{saved:true,linked}});assert.notEqual((await s.call('common-tasks/save',{reviewId:r.data.reviewId,approved:true})).status,200);}const links=await s.rows('common_task_link');assert.equal(links.length,1);assert.equal(links[0].version,3);assert.deepEqual((await s.get(s.f.course.id))[0].payload,before.payload);assert.equal((await s.rows('task')).length,1);assert.equal(s.writes(),3);const current=await s.begin();assert.equal(current.status,200);assert.equal(current.data.projectProgress.total,1);assert.equal(current.data.projectProgress.completed,1);assert.equal(current.data.projectProgress.percentage,100);assert.equal(JSON.stringify(current.data).includes(s.f.course.id),false);});
test('scope, login, POST, CSRF and opaque-only inputs are enforced before writes',async t=>{const off=await setup(t,{enabled:false});assert.equal((await off.call('common-tasks/begin',{})).status,404);const anon=await setup(t,{signed:false});assert.equal((await anon.call('common-tasks/begin',{})).status,401);const s=await setup(t);assert.equal((await s.call('common-tasks/begin')).status,404);for(const h of [{origin:'https://foreign.test'},{'x-cc-csrf':'bad'},{'x-cc-request':'bad'}])assert.equal((await s.call('common-tasks/begin',{},h)).status,403);for(const body of [{taskId:s.f.task.id},{referenceReadToken:'bad'},{referenceReadToken:'a'.repeat(43),ownerId:owner}])assert.equal((await s.call('common-tasks/begin',body)).status,409);assert.equal(s.writes(),0);});
test('cancel, new source browsing, sign-out and revoked sessions retire old membership approval',async t=>{for(const action of ['cancel','browse','logout','revoke']){const s=await setup(t),r=await s.review();assert.equal(r.status,200);if(action==='cancel')await s.call('common-tasks/cancel',{});if(action==='browse')await s.call('projects/references-list',{query:'',kind:'all',section:'all',offset:0});if(action==='logout')await s.call('logout',{});if(action==='revoke')s.revoke();assert.notEqual((await s.call('common-tasks/save',{reviewId:r.data.reviewId,approved:true})).status,200);assert.equal(s.writes(),0);}});
