test('delayed target opening cannot revive after cancel or a new source intent',async t=>{for(const action of ['cancel','browse']){const s=await setup(t),list=await s.call('projects/references-list',{query:'',kind:'project',section:'all',offset:0}),base=s.api.getPrivateProject;let release,entered;const gate=new Promise(r=>{release=r;}),started=new Promise(r=>{entered=r;});s.api.getPrivateProject=async(...args)=>{entered();await gate;return base(...args);};const pending=s.call('common-tasks/begin',{referenceReadToken:list.data.records[0].referenceReadToken});await started;if(action==='cancel')await s.call('common-tasks/cancel',{});else await s.call('projects/references-list',{query:'',kind:'all',section:'all',offset:0});release();assert.equal((await pending).status,409);assert.equal(s.writes(),0);}});

