test('SQL-backed project roll-up counts one original step linked under root and child only once',async t=>{const s=await setup(t,{hierarchy:true}),child='abcdabcd-abcd-4bcd-8bcd-000000000777',payload={...s.f.project.payload,title:'Smaller project'};await s.db.query("insert into public.cc_records(id,owner_id,household_id,visibility,section,item_type,origin,payload) values($1,$2,null,'private','Work','project','PRIVATE_COOKIE_PROJECT',$3)",[child,owner,JSON.stringify(payload)]);await s.db.query('select public.cc_set_project_hierarchy_link($1,1,$2,1,0,true)',[s.f.project.id,child]);let review=await s.review();assert.equal(review.status,200);assert.equal((await s.call('common-tasks/save',{reviewId:review.data.reviewId,approved:true})).status,200);let source=(await s.get(s.f.course.id))[0],project=(await s.get(child))[0];await s.db.query('select public.cc_set_common_task_link($1::jsonb,$2,$3::jsonb,$4,0,true)',[JSON.stringify(s.f.taskReference),source.version,JSON.stringify({kind:'project',recordId:child}),project.version]);const list=await s.call('projects/references-list',{query:'Manual project',kind:'project',section:'all',offset:0});const body={referenceReadToken:list.data.records[0].referenceReadToken,query:'',offset:0,includeSubprojects:true},combined=await s.call('common-tasks/begin',body);assert.equal(combined.status,200);assert.equal(combined.data.includeSubprojects,true);assert.equal(combined.data.hierarchyAvailable,true);assert.equal(combined.data.projectProgress.linkedTotal,1);assert.equal(combined.data.projectProgress.completed,1);assert.equal(JSON.stringify(combined.data).includes(child),false);await s.db.query('select public.cc_set_common_task_link($1::jsonb,$2,$3::jsonb,$4,1,false)',[JSON.stringify(s.f.taskReference),(await s.get(source.id))[0].version,JSON.stringify(s.f.projectReference),(await s.get(s.f.project.id))[0].version]);const current=await s.call('projects/references-list',{query:'Manual project',kind:'project',section:'all',offset:0});body.referenceReadToken=current.data.records[0].referenceReadToken;const inherited=await s.call('common-tasks/begin',body);assert.equal(inherited.status,200);assert.equal(inherited.data.projectProgress.linkedTotal,1);const direct=await s.call('common-tasks/begin',{...body,includeSubprojects:false});assert.equal(direct.status,200);assert.equal(direct.data.projectProgress.linkedTotal,0);});

test('ordinary project task list includes canonical steps and opens the verified original course with one-use authority',async t=>{const s=await setup(t),link=await s.review();assert.equal((await s.call('common-tasks/save',{reviewId:link.data.reviewId,approved:true})).status,200);const projects=await s.call('projects/list',{query:'',section:'all',status:'all',offset:0});assert.equal(projects.status,200);const token=projects.data.projects[0].projectToken,list=await s.call('projects/tasks-list',{projectToken:token,query:'',offset:0,linkedOnly:true});assert.equal(list.status,200);assert.equal(list.data.progress.linkedTotal,1);assert.equal(list.data.tasks.length,1);const task=list.data.tasks[0];assert.equal(task.sourceKind,'school-step');assert.equal(task.completed,true);assert.equal(JSON.stringify(list.data).includes('Exact <literal> notes'),false);assert.equal(JSON.stringify(list.data).includes(s.f.course.id),false);assert.equal((await s.call('projects/tasks-source-read',{taskToken:task.taskToken},{'x-cc-csrf':'bad'})).status,403);const opened=await s.call('projects/tasks-source-read',{taskToken:task.taskToken});assert.equal(opened.status,200);assert.equal(opened.data.sourceKind,'school-step');assert.equal(opened.data.record.notes,s.f.course.payload.notes);assert.equal(opened.data.record.title,s.f.course.payload.title);assert.equal(opened.data.assessmentTitle,s.f.course.payload.assessments[0].title);assert.equal(opened.data.record.assessments[0].tasks[0].title,s.f.course.payload.assessments[0].tasks[0].title);assert.equal(opened.data.record.readOnly,true);assert.equal((await s.call('projects/tasks-source-read',{taskToken:task.taskToken})).status,409);assert.equal(s.writes(),1);});

test('canonical link reviews from the existing project task panel preserve one membership and original task content',async t=>{const s=await setup(t),first=await s.review();await s.call('common-tasks/save',{reviewId:first.data.reviewId,approved:true});const projects=await s.call('projects/list',{query:'',section:'all',status:'all',offset:0}),projectToken=projects.data.projects[0].projectToken,list=await s.call('projects/tasks-list',{projectToken,query:'',offset:0,linkedOnly:true});const review=await s.call('projects/tasks-review',{taskToken:list.data.tasks[0].taskToken,linked:false});assert.equal(review.status,200);const saved=await s.call('projects/tasks-save',{reviewId:review.data.reviewId,approved:true});assert.equal(saved.status,200);assert.equal(saved.data.linked,false);assert.equal((await s.rows('common_task_link')).length,1);assert.deepEqual((await s.get(s.f.course.id))[0].payload,s.f.course.payload);const current=await s.call('projects/tasks-list',{projectToken,query:'',offset:0,linkedOnly:true});assert.equal(current.status,200);assert.equal(current.data.progress.linkedTotal,0);assert.equal(current.data.matchCount,0);});

test('stale and replaced typed task selections cannot reveal a changed academic source',async t=>{const s=await setup(t),first=await s.review();await s.call('common-tasks/save',{reviewId:first.data.reviewId,approved:true});const projects=await s.call('projects/list',{query:'',section:'all',status:'all',offset:0}),projectToken=projects.data.projects[0].projectToken;let list=await s.call('projects/tasks-list',{projectToken,query:'',offset:0,linkedOnly:true});const old=list.data.tasks[0].taskToken;list=await s.call('projects/tasks-list',{projectToken,query:'',offset:0,linkedOnly:true});assert.equal((await s.call('projects/tasks-source-read',{taskToken:old})).status,409);await s.db.query("update public.cc_records set payload=payload||'{\"changed\":true}'::jsonb where id=$1",[s.f.course.id]);assert.equal((await s.call('projects/tasks-source-read',{taskToken:list.data.tasks[0].taskToken})).status,409);assert.equal(s.writes(),1);});

test('explicit canonical mode preserves the existing manual-to-manual reviewed link workflow',async t=>{const s=await setup(t);s.api.getTaskProjectMembership=async(_t,taskId,projectId)=>(await s.rows('project_task_link')).filter(row=>row.payload.taskId===taskId&&row.payload.projectId===projectId);let ordinaryWrites=0;s.api.setTaskProjectLink=async(_t,v)=>{ordinaryWrites++;return(await s.db.query('select public.cc_set_task_project_link($1,$2,$3,$4,$5,$6) result',[v.taskId,v.taskVersion,v.projectId,v.projectVersion,v.linkVersion,v.linked])).rows[0].result;};const projects=await s.call('projects/list',{}),projectToken=projects.data.projects[0].projectToken;for(const linked of [true,false]){const list=await s.call('projects/tasks-list',{projectToken,query:'Manual task',linkedOnly:false,offset:0});assert.equal(list.status,200);assert.equal(list.data.tasks[0].sourceKind,'task');const review=await s.call('projects/tasks-review',{taskToken:list.data.tasks[0].taskToken,linked});assert.equal(review.status,200);const saved=await s.call('projects/tasks-save',{reviewId:review.data.reviewId,approved:true});assert.equal(saved.status,200);assert.equal(saved.data.linked,linked);}assert.equal(ordinaryWrites,2);assert.equal(s.writes(),0);assert.equal((await s.rows('project_task_link')).length,1);assert.equal((await s.rows('common_task_link')).length,0);assert.deepEqual((await s.get(s.f.task.id))[0].payload,s.f.task.payload);});

test('uncertain academic unlink from ordinary project tasks consumes its approval without retry',async t=>{const s=await setup(t),created=await s.review();await s.call('common-tasks/save',{reviewId:created.data.reviewId,approved:true});const projects=await s.call('projects/list',{}),projectToken=projects.data.projects[0].projectToken,list=await s.call('projects/tasks-list',{projectToken,linkedOnly:true,query:'',offset:0}),review=await s.call('projects/tasks-review',{taskToken:list.data.tasks[0].taskToken,linked:false}),base=s.api.setCommonTaskLink;s.api.setCommonTaskLink=async(...args)=>{await base(...args);throw Error('Fictional lost acknowledgement');};const body={reviewId:review.data.reviewId,approved:true};assert.equal((await s.call('projects/tasks-save',body)).status,503);assert.equal((await s.call('projects/tasks-save',body)).status,409);assert.equal(s.writes(),2);const links=await s.rows('common_task_link');assert.equal(links.length,1);assert.notEqual(links[0].deleted_at,null);});

test('typed academic selection edits only its original course through the existing reviewed School engine',async t=>{const s=await setup(t,{editing:true}),created=await s.review();await s.call('common-tasks/save',{reviewId:created.data.reviewId,approved:true});const projects=await s.call('projects/list',{}),projectToken=projects.data.projects[0].projectToken,list=await s.call('projects/tasks-list',{projectToken,linkedOnly:true,query:'',offset:0}),taskToken=list.data.tasks[0].taskToken,opened=await s.call('projects/tasks-source-manage',{taskToken});assert.equal(opened.status,200);assert.equal(opened.data.sourceKind,'school-step');assert.equal(opened.data.taskTitle,s.f.course.payload.assessments[0].tasks[0].title);assert.equal(opened.data.editor.sourceKind,'school-course');assert.equal(opened.data.editor.edit.kind,'course');assert.equal(JSON.stringify(opened.data).includes(s.f.course.id),false);const refresh=await s.call('school/edit-read',{schoolReadToken:opened.data.schoolReadToken});assert.equal(refresh.status,200);assert.deepEqual(refresh.data.fields,opened.data.editor.edit.fields);const fields={...refresh.data.fields,notes:'\nReviewed original course notes\n<literal> retained.'},review=await s.call('school/edit-review',{editToken:refresh.data.editToken,fields});assert.equal(review.status,200);assert.equal((await s.call('school/edit-save',{reviewId:review.data.reviewId,approved:true})).status,200);const after=(await s.get(s.f.course.id))[0];assert.deepEqual(after.payload,{...s.f.course.payload,notes:fields.notes});assert.equal((await s.rows('common_task_link')).length,1);assert.equal((await s.rows('task')).length,1);assert.equal((await s.call('projects/tasks-source-manage',{taskToken})).status,409);const updated=await s.call('projects/tasks-list',{projectToken,linkedOnly:true,query:'',offset:0});assert.equal(updated.status,200);assert.equal(updated.data.progress.linkedCompleted,1);});

