test('new source-edit intent retires prior School approval and cannot revive after cancellation',async t=>{const s=await setup(t,{editing:true}),created=await s.review();await s.call('common-tasks/save',{reviewId:created.data.reviewId,approved:true});const projects=await s.call('projects/list',{}),projectToken=projects.data.projects[0].projectToken,list=async()=>s.call('projects/tasks-list',{projectToken,linkedOnly:true,query:'',offset:0});let view=await list();const opened=await s.call('projects/tasks-source-manage',{taskToken:view.data.tasks[0].taskToken}),editor=opened.data.editor.edit,prior=await s.call('school/edit-review',{editToken:editor.editToken,fields:{...editor.fields,notes:'Fictional superseded notes'}});assert.equal(prior.status,200);view=await list();const base=s.api.getCommonTaskSource;let release,entered,first=true;const gate=new Promise(r=>release=r),started=new Promise(r=>entered=r);s.api.getCommonTaskSource=async(...args)=>{if(first&&args[1].recordId===s.f.course.id){first=false;entered();await gate;}return base(...args);};const pending=s.call('projects/tasks-source-manage',{taskToken:view.data.tasks[0].taskToken});await started;assert.equal((await s.call('school/edit-save',{reviewId:prior.data.reviewId,approved:true})).status,409);assert.equal((await s.call('school/edit-cancel',{})).status,200);release();assert.equal((await pending).status,409);assert.deepEqual((await s.get(s.f.course.id))[0].payload,s.f.course.payload);});

test('typed manual source handoff reuses the existing original-task review/save engine without copying or dropping extensions',async t=>{const s=await setup(t,{taskEditing:true}),subtasks=[{id:'abcdabcd-abcd-4bcd-8bcd-000000000811',title:'Original complete step',done:true},{id:'abcdabcd-abcd-4bcd-8bcd-000000000812',title:'Original open step',done:false}],before={...s.f.task.payload,day:'2026-11-19',description:'\nOriginal manual details',subtasks,extension:{keep:'Unknown saved task field'}};await s.db.query('update public.cc_records set payload=$1 where id=$2',[JSON.stringify(before),s.f.task.id]);const projects=await s.call('projects/list',{}),projectToken=projects.data.projects[0].projectToken,list=await s.call('projects/tasks-list',{projectToken,linkedOnly:false,query:'Manual task',offset:0}),taskToken=list.data.tasks[0].taskToken,opened=await s.call('projects/tasks-source-manage',{taskToken});assert.equal(opened.status,200);assert.equal(opened.data.sourceKind,'task');assert.equal(opened.data.completed,false);assert.equal(opened.data.editor.description,before.description);assert.equal(opened.data.editor.day,before.day);assert.equal(JSON.stringify(opened.data).includes(s.f.task.id),false);const fields={editToken:opened.data.editToken,title:'Reviewed original manual task',description:'\nReviewed manual details',day:before.day,section:'Work'},review=await s.call('tasks/edit-review',fields);assert.equal(review.status,200);assert.equal((await s.call('tasks/edit-save',{reviewId:review.data.reviewId,approved:true})).status,200);const after=(await s.get(s.f.task.id))[0];assert.equal(after.payload.title,fields.title);assert.equal(after.payload.description,fields.description);assert.deepEqual(after.payload.subtasks,subtasks);assert.deepEqual(after.payload.extension,before.extension);assert.equal(after.payload.done,false);assert.equal((await s.rows('task')).length,1);assert.equal((await s.call('projects/tasks-source-manage',{taskToken})).status,409);});

