test('superseded task approvals and cancelled manual handoffs cannot revive after delayed source access',async t=>{for(const cancellation of ['tasks/edit-cancel','school/edit-cancel']){const s=await setup(t,{taskEditing:true,editing:true});await s.db.query("update public.cc_records set payload=payload||'{\"day\":\"2026-11-19\"}'::jsonb where id=$1",[s.f.task.id]);const before=(await s.get(s.f.task.id))[0],projects=await s.call('projects/list',{}),projectToken=projects.data.projects[0].projectToken,list=async()=>s.call('projects/tasks-list',{projectToken,query:'Manual task',offset:0,linkedOnly:false});let tasks=await list();const first=await s.call('projects/tasks-source-manage',{taskToken:tasks.data.tasks[0].taskToken});assert.equal(first.status,200);const editor=first.data.editor,prior=await s.call('tasks/edit-review',{editToken:first.data.editToken,title:'Superseded draft',day:editor.day,section:editor.section,description:editor.description});assert.equal(prior.status,200);tasks=await list();const base=s.api.getCommonTaskSource;let release,entered,firstRead=true;const gate=new Promise(r=>release=r),started=new Promise(r=>entered=r);s.api.getCommonTaskSource=async(...args)=>{if(firstRead&&args[1].recordId===s.f.task.id){firstRead=false;entered();await gate;}return base(...args);};const pending=s.call('projects/tasks-source-manage',{taskToken:tasks.data.tasks[0].taskToken});await started;assert.equal((await s.call('tasks/edit-save',{reviewId:prior.data.reviewId,approved:true})).status,409);assert.equal((await s.call(cancellation,{})).status,200);release();assert.equal((await pending).status,409);assert.deepEqual((await s.get(s.f.task.id))[0].payload,before.payload);}});

test('Brief selected-project linked tasks reuse canonical sources without read or mutation authority',async t=>{const s=await setup(t),r=await s.review();await s.call('common-tasks/save',{reviewId:r.data.reviewId,approved:true});const overview=await s.call('projects/overview',{});assert.equal(overview.status,200);const key=overview.data.projects[0].projectReadToken,before=await s.rows('common_task_link'),sources=await s.rows('school_fixture');const result=await s.call('search/project-tasks',{projectReadToken:key,offset:0});assert.equal(result.status,200);assert.equal(result.data.readOnly,true);assert.equal(result.data.progress.linkedTotal,1);assert.equal(result.data.progress.completed,1);assert.equal(result.data.manualStatus,s.f.project.payload.status);assert.equal(result.data.tasks[0].sourceKind,'school-step');assert.equal(result.data.tasks[0].direct,true);assert.doesNotMatch(JSON.stringify(result.data),/recordId|assessmentId|academicId|owner_id|description|notes|taskToken|projectToken|payload/);assert.deepEqual(await s.rows('common_task_link'),before);assert.deepEqual(await s.rows('school_fixture'),sources);assert.equal(s.writes(),1);for(const patch of [{offset:null},{offset:1},{offset:50},{includeSubprojects:true},{projectReadToken:'x'.repeat(43)},{recordId:s.f.project.id}])assert.notEqual((await s.call('search/project-tasks',{projectReadToken:key,...patch})).status,200);assert.equal((await s.call('search/project-tasks',{projectReadToken:key},{'x-cc-csrf':'wrong'})).status,403);await s.call('projects/overview',{});assert.equal((await s.call('search/project-tasks',{projectReadToken:key})).status,409);});

test('selected-project task summary refuses absent scope, unauthenticated access, source drift and cleared late reads',async t=>{for(const options of [{enabled:false},{signed:false}]){const s=await setup(t,options);assert.notEqual((await s.call('search/project-tasks',{projectReadToken:'x'.repeat(43)})).status,200);}const s=await setup(t),overview=await s.call('projects/overview',{}),key=overview.data.projects[0].projectReadToken;await s.db.query("update public.cc_records set payload=jsonb_set(payload,'{description}','\"Changed original\"') where id=$1",[s.f.project.id]);assert.equal((await s.call('search/project-tasks',{projectReadToken:key})).status,409);const fresh=await s.call('projects/overview',{}),newKey=fresh.data.projects[0].projectReadToken,original=s.api.getCommonTaskSource;let entered,release;const began=new Promise(r=>{entered=r;}),wait=new Promise(r=>{release=r;});s.api.getCommonTaskSource=async(...args)=>{entered();await wait;return original(...args);};const pending=s.call('search/project-tasks',{projectReadToken:newKey});await began;await s.call('projects/overview',{});release();assert.equal((await pending).status,409);assert.equal(s.writes(),0);});

