test('academic inventory manual editor handoff reuses reviewed task saves and preserves checklist identities and extension payload',async t=>{const s=await setup(t,{taskReading:true,taskEditing:true}),payload={...s.f.task.payload,day:'2026-11-19',description:'Original manual source',subtasks:[{id:'abcdabcd-abcd-4bcd-8bcd-000000000898',title:'Saved completed step',done:true}],extension:{keep:'Original extra data'}};await s.db.query('update public.cc_records set payload=$1 where id=$2',[JSON.stringify(payload),s.f.task.id]);await s.db.query('select public.cc_set_common_task_link($1::jsonb,$2,$3::jsonb,$4,0,true)',[JSON.stringify({kind:'task',recordId:s.f.task.id}),(await s.get(s.f.task.id))[0].version,JSON.stringify({kind:'school-course',recordId:s.f.course.id}),(await s.get(s.f.course.id))[0].version]);const refs=await s.call('projects/references-list',{kind:'school-course',query:'',section:'all',offset:0}),begin=await s.call('common-tasks/begin',{referenceReadToken:refs.data.records[0].referenceReadToken}),summary=await s.call('common-tasks/target-summary',{viewId:begin.data.viewId,targetToken:begin.data.targets[0].targetToken}),manual=summary.data.tasks.find(t=>t.sourceKind==='task'),body={viewId:begin.data.viewId,sourceReadToken:manual.sourceReadToken},opened=await s.call('common-tasks/source-manage',body);assert.equal(opened.status,200);assert.equal(opened.data.editor.description,payload.description);assert.doesNotMatch(JSON.stringify(opened.data),/recordId|owner_id|payload|sourceReadToken/);const review=await s.call('tasks/edit-review',{editToken:opened.data.editToken,title:'Reviewed academic inventory source',day:payload.day,section:'Work',description:'Reviewed exact description'});assert.equal(review.status,200);assert.equal((await s.call('tasks/edit-save',{reviewId:review.data.reviewId,approved:true})).status,200);const after=(await s.get(s.f.task.id))[0];assert.equal(after.payload.title,'Reviewed academic inventory source');assert.deepEqual(after.payload.subtasks,payload.subtasks);assert.deepEqual(after.payload.extension,payload.extension);assert.equal((await s.rows('task')).length,1);assert.equal((await s.rows('common_task_link')).length,1);assert.equal((await s.call('common-tasks/source-manage',body)).status,409);});

test('cancelled academic inventory manual-editor handoff cannot revive after delayed original task reading',{timeout:15000},async t=>{const s=await setup(t,{taskReading:true,taskEditing:true});await s.db.query("update public.cc_records set payload=jsonb_set(payload,'{day}','\"2026-11-19\"') where id=$1",[s.f.task.id]);await s.db.query('select public.cc_set_common_task_link($1::jsonb,$2,$3::jsonb,$4,0,true)',[JSON.stringify({kind:'task',recordId:s.f.task.id}),(await s.get(s.f.task.id))[0].version,JSON.stringify({kind:'school-course',recordId:s.f.course.id}),(await s.get(s.f.course.id))[0].version]);const refs=await s.call('projects/references-list',{kind:'school-course',query:'',section:'all',offset:0}),begin=await s.call('common-tasks/begin',{referenceReadToken:refs.data.records[0].referenceReadToken}),summary=await s.call('common-tasks/target-summary',{viewId:begin.data.viewId,targetToken:begin.data.targets[0].targetToken}),manual=summary.data.tasks.find(t=>t.sourceKind==='task'),before=(await s.get(s.f.task.id))[0],body={viewId:begin.data.viewId,sourceReadToken:manual.sourceReadToken};assert.equal((await s.call('common-tasks/source-manage',body,{'x-cc-csrf':'wrong'})).status,403);let entered,release;t.after(()=>release?.());const started=new Promise(r=>{entered=r;}),wait=new Promise(r=>{release=r;}),original=s.api.getPrivateTaskDetails;s.api.getPrivateTaskDetails=async(...args)=>{entered();await wait;return original(...args);};const pending=s.call('common-tasks/source-manage',body);await started;assert.equal((await s.call('tasks/edit-cancel',{})).status,200);release();assert.equal((await pending).status,409);assert.deepEqual((await s.get(s.f.task.id))[0],before);assert.equal(s.writes(),0);});

test('academic inventory School editor handoff preserves original payload and supports bound nested refresh without Task-edit scope',async t=>{const s=await setup(t,{editing:true}),before=(await s.get(s.f.course.id))[0],refs=await s.call('projects/references-list',{kind:'school-course',query:'',section:'all',offset:0}),begin=await s.call('common-tasks/begin',{referenceReadToken:refs.data.records[0].referenceReadToken}),summary=await s.call('common-tasks/target-summary',{viewId:begin.data.viewId,targetToken:begin.data.targets[1].targetToken}),body={viewId:begin.data.viewId,sourceReadToken:summary.data.tasks[0].sourceReadToken},opened=await s.call('common-tasks/source-manage',body);assert.equal(opened.status,200);assert.equal(opened.data.editor.sourceKind,'school-course');assert.equal(opened.data.editor.edit.fields.notes,before.payload.notes);assert.doesNotMatch(JSON.stringify(opened.data),/recordId|academicId|owner_id|payload/);assert.equal((await s.call('common-tasks/source-manage',body)).status,409);const refreshed=await s.call('school/edit-read',{schoolReadToken:opened.data.schoolReadToken});assert.equal(refreshed.status,200);const fields={...refreshed.data.fields,notes:'\nReviewed original academic inventory source'},review=await s.call('school/edit-review',{editToken:refreshed.data.editToken,fields});assert.equal(review.status,200);assert.equal((await s.call('school/edit-save',{reviewId:review.data.reviewId,approved:true})).status,200);const after=(await s.get(s.f.course.id))[0];assert.deepEqual(after.payload,{...before.payload,notes:fields.notes});assert.equal((await s.rows('task')).length,1);assert.equal(s.writes(),0);const latest=await s.call('projects/references-list',{kind:'school-course',query:'',section:'all',offset:0});assert.equal(latest.status,200);});

test('cancelled academic inventory School handoff cannot revive after delayed source inventory reading',{timeout:15000},async t=>{const s=await setup(t,{editing:true}),refs=await s.call('projects/references-list',{kind:'school-course',query:'',section:'all',offset:0}),begin=await s.call('common-tasks/begin',{referenceReadToken:refs.data.records[0].referenceReadToken}),summary=await s.call('common-tasks/target-summary',{viewId:begin.data.viewId,targetToken:begin.data.targets[1].targetToken}),before=(await s.get(s.f.course.id))[0];let entered,release;t.after(()=>release?.());const started=new Promise(r=>{entered=r;}),wait=new Promise(r=>{release=r;}),original=s.api.getCommonTaskSource;s.api.getCommonTaskSource=async(...args)=>{entered();await wait;return original(...args);};const pending=s.call('common-tasks/source-manage',{viewId:begin.data.viewId,sourceReadToken:summary.data.tasks[0].sourceReadToken});await started;assert.equal((await s.call('school/edit-cancel',{})).status,200);release();assert.equal((await pending).status,409);assert.deepEqual((await s.get(s.f.course.id))[0],before);assert.equal(s.writes(),0);});
